// >>> largest_divisor(15)
// 5
func largest_divisor(n int) int {
    if n <= 1 {
        return 0
    }

    // Start from n/2 and go downwards to find the largest divisor
    for i := n / 2; i >= 1; i-- {
        if n%i == 0 {
            return i
        }
    }

    // This should never be reached for n > 1
    return 1
