import (
    "testing"
    "fmt"
)

// Checks if given string is a palindrome
// >>> is_palindrome("")
// true
// >>> is_palindrome("aba")
// true
// >>> is_palindrome("aaaaa")
// true
// >>> is_palindrome("zbcd")
// false
func is_palindrome(text string) bool {
    // Empty string is considered a palindrome
    if len(text) <= 1 {
        return true
    }

    // Compare characters from start and end moving inward
    left := 0
    right := len(text) - 1

    for left < right {
        if text[left] != text[right] {
            return false
        }
        left++
        right--
    }

    return true
}
