// brackets is a string of "<" and ">".
// return true if every opening bracket has a corresponding closing bracket.
// >>> correct_bracketing("<")
// false
// >>> correct_bracketing("<>")
// true
// >>> correct_bracketing("<<><>>")
// true
// >>> correct_bracketing("><<>")
// false
func correct_bracketing(brackets string) bool {
    count := 0
    for _, bracket := range brackets {
        if bracket == '<' {
            count++
        } else if bracket == '>' {
            count--
            // If we have more closing brackets than opening ones at any point,
            // the string is not correctly bracketed
            if count < 0 {
                return false
            }
        }
    }
    // The string is correctly bracketed only if every opening bracket has a matching closing bracket
    return count == 0
}
