// * 1 <= nodes.length <= 10000
// * 0 <= node.value
func pluck(arr []int) []int {
    if len(arr) == 0 {
        return []int{}
    }

    smallestEven := -1
    index := -1

    for i, val := range arr {
        if val%2 == 0 && (smallestEven == -1 || val < smallestEven) {
            smallestEven = val
            index = i
        }
    }

    if smallestEven == -1 {
        return []int{}
    }

    return []int{smallestEven, index}
