    "fmt"
)

// Your task is to write a function that returns true if a number x is a simple
// power of n and false in other cases.
// x is a simple power of n if n**int=x
// For example:
// >>> is_simple_power(1, 4)
// true
// >>> is_simple_power(2, 2)
// true
// >>> is_simple_power(8, 2)
// true
// >>> is_simple_power(3, 2)
// false
// >>> is_simple_power(3, 1)
// false
// >>> is_simple_power(5, 3)
// false
func is_simple_power(x int, n int) bool {
    // Handle special cases
    if x == 1 {
        return true // n^0 = 1 for any n != 0
    }
    if n == 1 {
        return false // 1^k = 1 for any k, so only true when x == 1
    }
    if n == 0 {
        return false // 0^k = 0 for k > 0, and undefined for k = 0
    }

    // Check if x is a power of n by repeatedly dividing by n
    current := x
    for current > 1 {
        if current % n != 0 {
            return false
        }
        current /= n
    }

    return current == 1
}
