// >>> solve(150)
// "110"
// >>> solve(147)
// "1100"
// Variables:
// @N integer
// Constraints: 0 ≤ N ≤ 10000.
// Output:
// a string of binary number
func solve(N int) string {
    // Calculate sum of digits of N
    digitSum := 0
    temp := N
    for temp > 0 {
        digitSum += temp % 10
        temp /= 10
    }

    // Convert the sum to binary string
    if digitSum == 0 {
        return "0"
    }

    binary := ""
    for digitSum > 0 {
        if digitSum%2 == 1 {
            binary = "1" + binary
        } else {
            binary = "0" + binary
        }
        digitSum /= 2
    }

    return binary
}
