// Implement a function that takes an non-negative integer and returns a list of the first n
// integers that are prime numbers and less than n.
// for example:
// >>> count_up_to(5)
// []int{2, 3}
// >>> count_up_to(11)
// []int{2, 3, 5, 7}
// >>> count_up_to(0)
// []int{}
// >>> count_up_to(20)
// []int{2, 3, 5, 7, 11, 13, 17, 19}
// >>> count_up_to(1)
// []int{}
// >>> count_up_to(18)
// []int{2, 3, 5, 7, 11, 13, 17}
func count_up_to(n int) []int {
    if n <= 2 {
        return []int{}
    }

    result := []int{}

    for num := 2; num < n; num++ {
        if isPrime(num) {
            result = append(result, num)
        }
    }

    return result
}

func isPrime(num int) bool {
    if num < 2 {
        return false
    }
    if num == 2 {
        return true
    }
    if num%2 == 0 {
        return false
    }

    // Check odd divisors up to sqrt(num)
    for i := 3; i*i <= num; i += 2 {
        if num%i == 0 {
            return false
        }
    }

    return true
}
