// A string is called palindrome if it reads the same backward as forward.
// You should return a list containing the result string and true/false for the check.
// Example
// >>> reverse_delete("abcde", "ae")
// []interface{}{"bcd", false}
// >>> reverse_delete("abcdef", "b")
// []interface{}{"acdef", false}
// >>> reverse_delete("abcdedcba", "ab")
// []interface{}{"cdedc", true}
func reverse_delete(s string, c string) []interface{} {
    // Create a map to store characters in c for O(1) lookup
    cChars := make(map[rune]bool)
    for _, char := range c {
        cChars[char] = true
    }

    // Build result string by excluding characters in c
    result := ""
    for _, char := range s {
        if !cChars[char] {
            result += string(char)
        }
    }

    // Check if result is palindrome
    isPalindrome := true
    n := len(result)
    for i := 0; i < n/2; i++ {
        if result[i] != result[n-1-i] {
            isPalindrome = false
            break
        }
    }

    return []interface{}{result, isPalindrome}
}
