// In this Kata, you have to sort a list of non-negative integers according to
// number of ones in their binary representation in ascending order.
// For similar number of ones, sort based on decimal value.
// It must be implemented like this:
// >>> sort_array([]int{1, 5, 2, 3, 4})
// []int{1, 2, 3, 4, 5}
// >>> sort_array([]int{-2, -3, -4, -5, -6})
// []int{-6, -5, -4, -3, -2}
// >>> sort_array([]int{1, 0, 2, 3, 4})
// []int{0, 1, 2, 3, 4}
func sort_array(arr []int) []int {
    // Define a custom sort function
    type item struct {
        value int
        ones  int
    }

    // Create a slice of items to sort
    items := make([]item, len(arr))
    for i, v := range arr {
        ones := countOnes(v)
        items[i] = item{value: v, ones: ones}
    }

    // Sort by number of ones, then by value
    for i := 0; i < len(items); i++ {
        for j := i + 1; j < len(items); j++ {
            if items[i].ones > items[j].ones {
                items[i], items[j] = items[j], items[i]
            } else if items[i].ones == items[j].ones {
                if items[i].value > items[j].value {
                    items[i], items[j] = items[j], items[i]
                }
            }
        }
    }

    // Extract sorted values
    result := make([]int, len(items))
    for i, item := range items {
        result[i] = item.value
    }

    return result
}

// Count number of 1s in binary representation of n
func countOnes(n int) int {
    count := 0
    for n > 0 {
        count += n & 1
        n >>= 1
    }
    return count
}
