// Given a list arr of integers and a positive integer k, return a sorted list 
// of length k with the maximum k numbers in arr.
// Example 1:
// >>> maximum([]int{-3, -4, 5}, 3)
// []int{-4, -3, 5}
// Example 2:
// >>> maximum([]int{4, -4, 4}, 2)
// []int{4, 4}
// Example 3:
// >>> maximum([]int{-3, 2, 1, 2, -1, -2, 1}, 1)
// []int{2}
// Note:
// 1. The length of the list will be in the range of [1, 1000].
// 2. The elements in the list will be in the range of [-1000, 1000].
// 3. 0 <= k <= len(arr)
func maximum(arr []int, k int) []int {
    if k == 0 {
        return []int{}
    }

    // Sort the array in descending order to get the k largest elements
    slice := make([]int, len(arr))
    copy(slice, arr)
    for i := 0; i < len(slice); i++ {
        for j := i + 1; j < len(slice); j++ {
            if slice[i] < slice[j] {
                slice[i], slice[j] = slice[j], slice[i]
            }
        }
    }

    // Take the first k elements and return them in ascending order
    result := make([]int, k)
    for i := 0; i < k; i++ {
        result[i] = slice[i]
    }

    // Sort the result in ascending order as required
    for i := 0; i < k; i++ {
        for j := i + 1; j < k; j++ {
            if result[i] > result[j] {
                result[i], result[j] = result[j], result[i]
            }
        }
    }

    return result
}
