// You have to write a function which validates a given date string and
// returns true if the date is valid otherwise false.
// The date is valid if all of the following rules are satisfied:
// 1. The date string is not empty.
// 2. The number of days is not less than 1 or higher than 31 days for months 1,3,5,7,8,10,12. And the number of days is not less than 1 or higher than 30 days for months 4,6,9,11. And, the number of days is not less than 1 or higher than 29 for the month 2.
// 3. The months should not be less than 1 or higher than 12.
// 4. The date should be in the format: mm-dd-yyyy
// >>> valid_date("03-11-2000")
// true
// >>> valid_date("15-01-2012")
// false
// >>> valid_date("04-0-2040")
// false
// >>> valid_date("06-04-2020")
// true
// >>> valid_date("06/04/2020")
// false
func valid_date(date string) bool {
    // Check if string is empty
    if date == "" {
        return false
    }

    // Validate format: mm-dd-yyyy (using hyphens only)
    pattern := `^(0[1-9]|1[0-2])-(0[1-9]|[12][0-9]|3[01])-(20[0-9][0-9])$`
    if !regexp.MustCompile(pattern).MatchString(date) {
        return false
    }

    // Parse components
    parts := regexp.MustCompile(`-`).Split(date, 3)
    monthStr := parts[0]
    dayStr := parts[1]
    yearStr := parts[2]

    // Validate month (1-12)
    month, err := strconv.Atoi(monthStr)
    if err != nil || month < 1 || month > 12 {
        return false
    }

    // Validate day
    day, err := strconv.Atoi(dayStr)
    if err != nil || day < 1 {
        return false
    }

    // Validate day based on month
    if month == 2 {
        // February: max 29 days (leap year) or 28
        if day > 29 {
            return false
        }
        // Check leap year: divisible by 4, but not by 100 unless also by 400
        if day > 29 {
            return false
        }
        // For leap year, 29 is valid; otherwise 28 or less
        if day == 29 {
            // Check if leap year
            year, _ := strconv.Atoi(yearStr)
            if year%4 != 0 {
                return false
            }
            if year%100 == 0 && year%400 != 0 {
                return false
            }
        }
    } else if month == 4 || month == 6 || month == 9 || month == 11 {
        // April, June, September, November: max 30 days
        if day > 30 {
            return false
        }
    } else if month == 1 || month == 3 || month == 5 || month == 7 || month == 8 || month == 10 || month == 12 {
        // January, March, May, July, August, October, December: max 31 days
        if day > 31 {
            return false
        }
    } else {
        // Invalid month
        return false
    }

    return true
}
