// "Example"
// >>> fix_spaces(" Example 1")
// "Example_1"
// >>> fix_spaces(" Example 2")
// "_Example_2"
// >>> fix_spaces(" Example 3")
// "_Example-3"
func fix_spaces(text string) string {
    result := ""
    i := 0
    for i < len(text) {
        if text[i] == ' ' {
            // Count consecutive spaces
            count := 1
            j := i + 1
            for j < len(text) && text[j] == ' ' {
                count++
                j++
            }

            // Replace with underscore if count <= 2, otherwise with hyphen
            if count <= 2 {
                for k := 0; k < count; k++ {
                    if k == 0 {
                        result += "_"
                    } else {
                        result += "_"
                    }
                }
            } else {
                result += "-"
            }
            i = j
        } else {
            result += string(text[i])
            i++
        }
    }
    return result
}
