// Your task is to implement a function that will simplify the expression
// x * n. The function returns true if x * n evaluates to a whole number and false
// otherwise. Both x and n, are string representation of a fraction, and have the following format,
// <numerator>/<denominator> where both numerator and denominator are positive whole numbers.
// You can assume that x, and n are valid fractions, and do not have zero as denominator.
// >>> simplify("1/5", "5/1")
// true
// >>> simplify("1/6", "2/1")
// false
// >>> simplify("7/10", "10/2")
// false
func simplify(x string, n string) bool {
    // Parse x and n to extract numerators and denominators
    xParts := strings.Split(x, "/")
    nParts := strings.Split(n, "/")

    xNum, _ := strconv.Atoi(xParts[0])
    xDen, _ := strconv.Atoi(xParts[1])
    nNum, _ := strconv.Atoi(nParts[0])
    nDen, _ := strconv.Atoi(nParts[1])

    // Multiply fractions: (xNum * nNum) / (xDen * nDen)
    totalNum := xNum * nNum
    totalDen := xDen * nDen

    // Check if the result is a whole number
    // A fraction is a whole number if numerator is divisible by denominator
    return totalNum%totalDen == 0
}
