// are not correct planet names. 
// Examples
// >>> bf("Jupiter", "Neptune")
// []interface{}{"Saturn", "Uranus"}
// >>> bf("Earth", "Mercury")
// "Venus"
// >>> bf("Mercury", "Uranus")
// []interface{}{"Venus", "Earth", "Mars", "Jupiter", "Saturn"}
func bf(planet1 string, planet2 string) []interface{} {
    planets := []string{"Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus", "Neptune"}

    // Check if either planet is valid
    idx1 := -1
    idx2 := -1
    for i, p := range planets {
        if p == planet1 {
            idx1 = i
        }
        if p == planet2 {
            idx2 = i
        }
    }

    // If either planet is not found, return empty slice
    if idx1 == -1 || idx2 == -1 {
        return []interface{}{}
    }

    // Determine the range between the two planets
    start := 0
    end := 0
    if idx1 < idx2 {
        start = idx1 + 1
        end = idx2
    } else {
        start = idx2 + 1
        end = idx1
    }

    // Build result slice
    result := make([]interface{}, 0, end-start+1)
    for i := start; i < end; i++ {
        result = append(result, planets[i])
    }

    return result
}
