        // Convert to lowercase for case-insensitive comparison
        lowerChar := rune('a' + (int(char) - int('A')) % 26)
        if char >= 'A' && char <= 'Z' {
            lowerChar = rune('a' + (int(char) - int('A')))
        }
        seen[lowerChar] = true
    }
    return len(seen)
}
