// brackets is a string of "<" and ">".
// return true if every opening bracket has a corresponding closing bracket.
// >>> correct_bracketing("<")
// false
// >>> correct_bracketing("<>")
// true
// >>> correct_bracketing("<<><>>")
// true
// >>> correct_bracketing("><<>")
// false
func correct_bracketing(brackets string) bool {
    count := 0
    for _, bracket := range brackets {
        if bracket == '<' {
            count++
        } else if bracket == '>' {
            count--
            if count < 0 {
                return false
            }
        }
    }
    return count == 0
}
