package is_simple_power_test

import (
    "testing"
    "fmt"
)

// is_simple_power returns true if x is a simple power of n, i.e., if there exists an integer k such that n^k = x.
// It returns false otherwise.
func is_simple_power(x int, n int) bool {
    // Handle edge cases
    if x == 1 {
        // Any number to the power 0 is 1, but we need to check if n^0 = 1
        // However, n^0 = 1 for any n ≠ 0, so if x == 1, then it's a simple power unless n == 0
        if n == 0 {
            return false // 0^k is never 1 for any k
        }
        return true
    }
    if n == 1 {
        // 1^k = 1 for any k, so only x == 1 works
        return x == 1
    }
    if n == -1 {
        // (-1)^k alternates between 1 and -1
        // So only if x is 1 or -1 and k is even or odd accordingly
        return x == 1 || x == -1
    }
    if n == 0 {
        // 0^k = 0 for k > 0, and 0^0 is undefined or 1
        // So only x == 0 for k > 0, but 0^0 is not defined
        if x == 0 {
            return true // 0^1 = 0, so valid
        }
        return false
    }

    // For other cases, we try to find a non-negative integer k such that n^k == x
    // Start with k = 0, then increment until we either find a match or exceed x
    power := 1
    for power < x {
        if power == x {
            return true
        }
        // Avoid overflow by checking if next multiplication would exceed x
        if power > x/(n) {
            break
        }
        power *= n
    }
    return power == x
}
```

