// You are given a string s.
// Your task is to check if the string is hapgo or not.
// A string is hapgo if its length is at least 3 and every 3 consecutive letters are distinct
// For example:
// >>> is_happy("a")
// false
// >>> is_happy("aa")
// false
// >>> is_happy("abcd")
// true
// >>> is_happy("aabb")
// false
// >>> is_happy("adb")
// true
// >>> is_happy("xyy")
// false
func is_happy(s string) bool {
    if len(s) < 3 {
        return false
    }

    for i := 0; i <= len(s)-3; i++ {
        // Check if the three consecutive letters at position i, i+1, i+2 are all distinct
        if s[i] == s[i+1] || s[i] == s[i+2] || s[i+1] == s[i+2] {
            return false
        }
    }
    return true
}
