package solve_test

import (
    "testing"
    "fmt"
)

// Given a positive integer N, return the total sum of its digits in binary.
// Example
// >>> solve(1000)
// "1"
// >>> solve(150)
// "110"
// >>> solve(147)
// "1100"
// Variables:
// @N integer
// Constraints: 0 ≤ N ≤ 10000.
// Output:
// a string of binary number
func solve(N int) string {
    // Calculate the sum of digits of N
    digitSum := 0
    for N > 0 {
        digitSum += N % 10
        N /= 10
    }

    // Convert the sum to binary string (without "0b" prefix)
    if digitSum == 0 {
        return "0"
    }

    binary := ""
    for digitSum > 0 {
        if digitSum%2 == 1 {
            binary = "1" + binary
        } else {
            binary = "0" + binary
        }
        digitSum /= 2
    }

    return binary
}
