package sort_array_test

import (
    "testing"
    "fmt"
)

// Given a list of non-negative integers, return a copy of the given list after sorting,
// you will sort the given list in ascending order if the sum( first index value, last index value) is odd,
// or sort it in descending order if the sum( first index value, last index value) is even.
// Note:
// * don't change the given list.
// Examples:
// >>> sort_array([]int{})
// []int{}
// >>> sort_array([]int{5})
// []int{5}
// >>> sort_array([]int{2, 4, 3, 0, 1, 5})
// []int{0, 1, 2, 3, 4, 5}
// >>> sort_array([]int{2, 4, 3, 0, 1, 5, 6})
// []int{6, 5, 4, 3, 2, 1, 0}
func sort_array(array []int) []int {
    // Handle empty array or single element
    if len(array) <= 1 {
        return append([]int{}, array...)
    }

    // Calculate sum of first and last elements
    sum := array[0] + array[len(array)-1]

    // Create a copy of the array to avoid modifying the original
    copyArray := make([]int, len(array))
    copy(copyArray, array)

    // Sort in ascending order if sum is odd, descending if even
    if sum%2 == 1 {
        // Ascending order
        for i := 0; i < len(copyArray)-1; i++ {
            for j := i + 1; j < len(copyArray); j++ {
                if copyArray[i] > copyArray[j] {
                    copyArray[i], copyArray[j] = copyArray[j], copyArray[i]
                }
            }
        }
    } else {
        // Descending order
        for i := 0; i < len(copyArray)-1; i++ {
            for j := i + 1; j < len(copyArray); j++ {
                if copyArray[i] < copyArray[j] {
                    copyArray[i], copyArray[j] = copyArray[j], copyArray[i]
                }
            }
        }
    }

    return copyArray
}
