package count_up_to_test

import (
	"fmt"
	"math"
)

// count_up_to takes a non-negative integer n and returns a list of the first n integers that are prime numbers and less than n.
// It returns all prime numbers less than n, in ascending order.
func count_up_to(n int) []int {
	if n <= 2 {
		return []int{}
	}

	primes := []int{}
	for num := 2; num < n; num++ {
		if isPrime(num) {
			primes = append(primes, num)
		}
	}
	return primes
}

// isPrime checks if a number is prime.
func isPrime(num int) bool {
	if num < 2 {
		return false
	}
	if num == 2 {
		return true
	}
	if num%2 == 0 {
		return false
	}
	for i := 3; i <= int(math.Sqrt(float64(num))); i += 2 {
		if num%i == 0 {
			return false
		}
	}
	return true
}
