// >>> count_nums([]int{})
// 0
// >>> count_nums([]int{-1, 11, -11})
// 1
// >>> count_nums([]int{1, 1, 2})
// 3
func count_nums(arr []int) int {
    count := 0
    for _, num := range arr {
        sum := 0
        absNum := num
        if num < 0 {
            absNum = -num
        }

        // Compute sum of digits of absolute value
        for absNum > 0 {
            digit := absNum % 10
            sum += digit
            absNum /= 10
        }

        // For negative numbers, the first digit is negative
        if num < 0 {
            // The first digit of the original number is negative
            firstDigit := num % 10
            if firstDigit == 0 {
                firstDigit = 0
            } else {
                firstDigit = -firstDigit
            }
            // We need to subtract the first digit from the sum of digits
            // But note: the sum of digits of the absolute value is the sum of all digits
            // So for negative, we subtract the first digit (which is negative, so we add it)
            // Actually, the problem says: "first signed digit will be negative"
            // So we take the first digit and make it negative
            // So total sum = (sum of digits of abs) - 2 * (first digit)
            // Wait: no — the signed digits are: -first_digit, then the rest positive
            // So total sum = -first_digit + (sum of remaining digits)
            // So we need to compute the sum of digits of the absolute value, then subtract 2 * first_digit
            // Because: sum of digits of abs = first_digit + rest
            // So total sum = -first_digit + (first_digit + rest) = rest
            // So total sum = (sum of digits of abs) - 2 * first_digit
            sum = sum - 2*(firstDigit)
        }

        if sum > 0 {
            count++
        }
    }
    return count
}
