// Task
// We are given two strings s and c, you have to deleted all the characters in s that are equal to any character in c
// then check if the result string is palindrome.
// A string is called palindrome if it reads the same backward as forward.
// You should return a list containing the result string and true/false for the check.
// Example
// >>> reverse_delete("abcde", "ae")
// []interface{}{"bcd", false}
// >>> reverse_delete("abcdef", "b")
// []interface{}{"acdef", false}
// >>> reverse_delete("abcdedcba", "ab")
// []interface{}{"cdedc", true}
func reverse_delete(s string, c string) []interface{} {
    // Create a map to track which characters in c we need to remove from s
    cChars := make(map[rune]bool)
    for _, char := range c {
        cChars[char] = true
    }

    // Build the result string by including only characters not in c
    result := ""
    for _, char := range s {
        if !cChars[char] {
            result += string(char)
        }
    }

    // Check if result is palindrome
    isPalindrome := true
    n := len(result)
    for i := 0; i < n/2; i++ {
        if result[i] != result[n-1-i] {
            isPalindrome = false
            break
        }
    }

    // Return result and palindrome check as interface{}
    return []interface{}{result, isPalindrome}
}
