package is_nested_test

import (
    "testing"
    "fmt"
)

// Create a function that takes a string as input which contains only square brackets.
// The function should return true if and only if there is a valid subsequence of brackets 
// where at least one bracket in the subsequence is nested.
// >>> is_nested("[[]]")
// true
// >>> is_nested("[]]]]]]][[[[[]")
// false
// >>> is_nested("[][]")
// false
// >>> is_nested("[]")
// false
// >>> is_nested("[[][]]")
// true
// >>> is_nested("[[]][[")
// true
func is_nested(myString string) bool {
    // We need to check if there's a nested pair of brackets.
    // A nested pair means one bracket contains another, i.e., a pair like "[[]]" or "[[][]]".
    // We can simulate this by tracking the depth of brackets.
    depth := 0
    maxDepth := 0
    hasNested := false

    for _, char := range myString {
        if char == '[' {
            depth++
            if depth > 1 {
                // We found a bracket that is inside another bracket
                hasNested = true
            }
            maxDepth = depth
        } else if char == ']' {
            depth--
        }
    }

    // If we ever had a depth > 1, then there was at least one nested pair
    return hasNested
}
