package simplify_test

import (
    "testing"
    "fmt"
)

// Your task is to implement a function that will simplify the expression
// x * n. The function returns true if x * n evaluates to a whole number and false
// otherwise. Both x and n, are string representation of a fraction, and have the following format,
// <numerator>/<denominator> where both numerator and denominator are positive whole numbers.
// You can assume that x, and n are valid fractions, and do not have zero as denominator.
// >>> simplify("1/5", "5/1")
// true
// >>> simplify("1/6", "2/1")
// false
// >>> simplify("7/10", "10/2")
// false
func simplify(x string, n string) bool {
    // Parse x and n into numerator/denominator
    partsX := parseFraction(x)
    partsN := parseFraction(n)

    // Multiply fractions: (a/b) * (c/d) = (a*c)/(b*d)
    num := partsX[0] * partsN[0]
    den := partsX[1] * partsN[1]

    // Check if the result is a whole number: numerator is divisible by denominator
    return num%den == 0
}

// parseFraction parses a string of the form "a/b" into [numerator, denominator]
func parseFraction(frac string) [2]int {
    parts := []string{}
    for i := 0; i < len(frac); i++ {
        if frac[i] == '/' {
            parts = append(parts, frac[:i])
            parts = append(parts, frac[i+1:])
            break
        }
    }
    num, _ := strconv.Atoi(parts[0])
    den, _ := strconv.Atoi(parts[1])
    return [2]int{num, den}
}
