// >>> compare([]int{0, 5, 0, 0, 0, 4}, []int{4, 1, 1, 0, 0, -2})
// []int{4, 4, 1, 0, 0, 6}
func compare(game []int, guess []int) []int {
    var result []int
    for i := 0; i < len(game); i++ {
        diff := abs(game[i] - guess[i])
        result = append(result, diff)
    }
    return result
}

// Helper function to compute absolute value
func abs(x int) int {
    if x < 0 {
        return -x
    }
    return x
}
