/// If there are no even values or the given vector is empty, return [].
/// Example 1:
/// >>> pluck(vec![4, 2, 3])
/// vec![2, 1]
/// Explanation: 2 has the smallest even value, and 2 has the smallest index.
/// Example 2:
/// >>> pluck(vec![1, 2, 3])
/// vec![2, 1]
/// Explanation: 2 has the smallest even value, and 2 has the smallest index.
/// Example 3:
/// >>> pluck(vec![])
/// Vec::<isize>::new()
/// Example 4:
/// >>> pluck(vec![5, 0, 3, 0, 4, 2])
/// vec![0, 1]
/// Explanation: 0 is the smallest value, but  there are two zeros,
/// so we will choose the first zero, which has the smallest index.
/// Constraints:
/// * 1 <= nodes.length <= 10000
/// * 0 <= node.value
fn pluck(arr: Vec<isize>) -> Vec<isize> {
    if arr.is_empty() {
        return vec![];
    }

    let mut min_even = None;
    let mut min_index = None;

    for (index, &value) in arr.iter().enumerate() {
        if value % 2 == 0 {
            if min_even.is_none() || value < min_even.unwrap() {
                min_even = Some(value);
                min_index = Some(index);
            } else if value == min_even.unwrap() {
                // If same even value, choose the one with smallest index
                // Since we iterate from left to right, the first occurrence will be kept
                // So we don't need to update if value == min_even
            }
        }
    }

    if let Some(_) = min_even {
        return vec![min_even.unwrap(), min_index.unwrap()];
    }

    vec![]
}
