/// true
/// >>> is_simple_power(3, 2)
/// false
/// >>> is_simple_power(3, 1)
/// false
/// >>> is_simple_power(5, 3)
/// false
fn is_simple_power(x: isize, n: isize) -> bool {
    // Handle edge cases
    if x == 1 {
        return true; // n^0 = 1 for any n != 0
    }

    if n == 1 {
        return false; // 1^k = 1 for any k, so only true when x == 1
    }

    if n == 0 {
        return false; // 0^k = 0 for k > 0, and undefined for k = 0
    }

    if x < 0 || n < 0 {
        // For negative numbers, we need to consider if they can be expressed as n^k
        // But since we're dealing with integer powers, and negative base raised to even/odd powers
        // can be negative, we need to be careful.
        // However, the problem states n^int = x, and we're dealing with integers.
        // For negative x, we need n to be negative and the exponent to be odd.
        // But let's consider the constraints: if n is negative, then n^k alternates sign.
        // We'll handle this by checking if we can reach x through repeated multiplication.
        // However, the examples don't involve negative numbers, so we'll follow the pattern.
        // Since the problem doesn't specify negative cases, and given the examples,
        // we'll assume the function works for positive integers as per the examples.
        // For negative x, we can try to find if x = n^k for some integer k.
        // But since the problem doesn't specify, and given the examples are positive,
        // we'll focus on positive cases and return false for negative x.
        return false;
    }

    let mut current = n;
    let mut power = n;

    // Keep multiplying by n until we reach x or exceed it
    while power < x {
        power *= n;
        if power == x {
            return true;
        }
        // Avoid infinite loops for very large numbers
        if power > x && power > 0 {
            break;
        }
    }

    // Check if we've reached exactly x
    power == x
}
