    let mut pile = Vec::new();
    let mut current_stones = n;

    for level in 1..=n {
        pile.push(current_stones);

        if level < n {
            if n % 2 == 1 {
                // n is odd: next odd number
                current_stones += 2;
            } else {
                // n is even: next even number
                current_stones += 2;
            }
        }
    }

    pile
