/// The date is valid if all of the following rules are satisfied:
/// 1. The date string is not empty.
/// 2. The number of days is not less than 1 or higher than 31 days for months 1,3,5,7,8,10,12. And the number of days is not less than 1 or higher than 30 days for months 4,6,9,11. And, the number of days is not less than 1 or higher than 29 for the month 2.
/// 3. The months should not be less than 1 or higher than 12.
/// 4. The date should be in the format: mm-dd-yyyy
/// >>> valid_date(String::from("03-11-2000"))
/// true
/// >>> valid_date(String::from("15-01-2012"))
/// false
/// >>> valid_date(String::from("04-0-2040"))
/// false
/// >>> valid_date(String::from("06-04-2020"))
/// true
/// >>> valid_date(String::from("06/04/2020"))
/// false
fn valid_date(date: String) -> bool {
    // Check if the string is empty
    if date.is_empty() {
        return false;
    }

    // Split by '-' to get mm, dd, yyyy
    let parts: Vec<&str> = date.split('-').collect();
    if parts.len() != 3 {
        return false;
    }

    let mm = parts[0].parse::<u8>().ok().unwrap_or(0);
    let dd = parts[1].parse::<u8>().ok().unwrap_or(0);
    let yyyy = parts[2].parse::<u8>().ok().unwrap_or(0);

    // Check month range
    if mm < 1 || mm > 12 {
        return false;
    }

    // Check day range based on month
    let is_feb = mm == 2;
    let is_valid_day = match mm {
        1 | 3 | 5 | 7 | 8 | 10 | 12 => dd >= 1 && dd <= 31,
        4 | 6 | 9 | 11 => dd >= 1 && dd <= 30,
        2 => {
            // February: check leap year for 29th day
            let is_leap = (yyyy % 4 == 0 && (yyyy % 100 != 0 || yyyy % 400 == 0));
            dd >= 1 && (dd <= 29 && (dd <= 28 || is_leap))
        }
        _ => false,
    };

    if !is_valid_day {
        return false;
    }

    // Check if day is valid (non-zero and within range)
    if dd < 1 || dd > 31 {
        return false;
    }

    // Ensure the day is valid for the specific month
    if mm == 2 && dd > 29 {
        return false;
    }
    if mm == 2 && dd == 29 && !((yyyy % 4 == 0 && (yyyy % 100 != 0 || yyyy % 400 == 0))) {
        return false;
    }

    true
}
