/// Create a function that returns a tuple (a, b), where 'a' is
/// the largest of negative integers, and 'b' is the smallest
/// of positive integers in a vector.
/// If there is no negative or positive integers, return them as None.
/// Examples:
/// >>> largest_smallest_integers(vec![2, 4, 1, 3, 5, 7])
/// (None, Some(1))
/// >>> largest_smallest_integers(vec![])
/// (None, None)
/// >>> largest_smallest_integers(vec![0])
/// (None, None)
fn largest_smallest_integers(lst: Vec<isize>) -> (Option<isize>, Option<isize>) {
    let mut largest_negative: Option<isize> = None;
    let mut smallest_positive: Option<isize> = None;

    for num in lst {
        if num < 0 {
            // For negative numbers, we want the largest (closest to zero)
            if let Some(current) = largest_negative {
                if num > current {
                    largest_negative = Some(num);
                }
            } else {
                largest_negative = Some(num);
            }
        } else if num > 0 {
            // For positive numbers, we want the smallest
            if let Some(current) = smallest_positive {
                if num < current {
                    smallest_positive = Some(num);
                }
            } else {
                smallest_positive = Some(num);
            }
        }
        // 0 is neither positive nor negative, so we ignore it
    }

    (largest_negative, smallest_positive)
}
