/// For a given vector of input numbers, calculate Mean Absolute Deviation
/// around the mean of this dataset.
/// Mean Absolute Deviation is the average absolute difference between each
/// element and a centerpoint (mean in this case):
/// MAD = average | x - x_mean |
/// >>> mean_absolute_deviation(vec![1.0, 2.0, 3.0, 4.0])
/// 1.0
fn mean_absolute_deviation(numbers: Vec<f64>) -> f64 {
    if numbers.is_empty() {
        return 0.0;
    }

    let mean: f64 = numbers.iter().sum() / numbers.len() as f64;
    let absolute_deviations: f64 = numbers.iter().map(|&x| (x - mean).abs()).sum();
    absolute_deviations / numbers.len() as f64
}
