/// Change numerical base of input number x to base.
/// return string representation after the conversion.
/// base numbers are less than 10.
/// >>> change_base(8, 3)
/// String::from("22")
/// >>> change_base(8, 2)
/// String::from("1000")
/// >>> change_base(7, 2)
/// String::from("111")
fn change_base(x: isize, base: isize) -> String {
    if x == 0 {
        return "0".to_string();
    }

    let mut num = x.abs();
    let mut result = String::new();

    while num > 0 {
        let remainder = num % base as isize;
        result = format!("{}{}", remainder, result);
        num /= base as isize;
    }

    if x < 0 {
        result = format!("-{}", result);
    }

    result
}
