/// Write a function vowels_count which takes a string representing
/// a word as input and returns the number of vowels in the string.
/// Vowels in this case are 'a', 'e', 'i', 'o', 'u'. Here, 'y' is also a
/// vowel, but only when it is at the end of the given word.
/// Example:
/// >>> vowels_count(String::from("abcde"))
/// 2
/// >>> vowels_count(String::from("ACEDY"))
/// 3
fn vowels_count(s: String) -> isize {
    let vowels = ['a', 'e', 'i', 'o', 'u', 'A', 'E', 'I', 'O', 'U'];
    let mut count = 0isize;

    for c in s.chars() {
        if vowels.contains(&c.to_ascii_lowercase()) {
            if c == 'y' || c == 'Y' {
                // Only count 'y' if it's at the end of the word
                if s.chars().nth(s.len() - 1) == Some(c) {
                    count += 1;
                }
            } else {
                count += 1;
            }
        }
    }

    count
}
