    assert_eq!(pluck(vec![5, 0, 3, 0, 4, 2]), vec![0, 1]);
    assert_eq!(pluck(vec![1, 3, 5, 7]), vec![0, 0]); // Wait — no even values, should be empty
    // Correction: no even values → should return empty
    assert_eq!(pluck(vec![1, 3, 5, 7]), vec![]);

