/// Your task is to write a function that returns true if a number x is a simple
/// power of n and false in other cases.
/// x is a simple power of n if n**int=x
/// For example:
/// >>> is_simple_power(1, 4)
/// true
/// >>> is_simple_power(2, 2)
/// true
/// >>> is_simple_power(8, 2)
/// true
/// >>> is_simple_power(3, 2)
/// false
/// >>> is_simple_power(3, 1)
/// false
/// >>> is_simple_power(5, 3)
/// false
fn is_simple_power(x: isize, n: isize) -> bool {
    // Handle edge cases
    if x == 1 {
        return true; // n^0 = 1 for any n != 0
    }
    if n == 1 {
        return false; // 1^k = 1 for any k, so only true when x == 1, which is handled above
    }
    if n == 0 {
        return false; // 0^k = 0 for k > 0, and undefined for k=0; x can't be non-zero
    }
    if x < 0 || n < 0 {
        // For negative x or n, we consider only integer powers, but negative base raised to even/odd powers
        // However, the problem states n^int = x, and we're dealing with integers.
        // For negative n, powers alternate sign; for negative x, we need odd powers of negative n.
        // But the examples don't involve negatives, and the problem likely assumes positive integers.
        // Given the examples, we assume positive x and n.
        return false;
    }

    let mut power = 1isize;
    while power < x {
        power *= n;
    }
    power == x
}
```

