    assert_eq!(is_simple_power(1, 4), true); // 4^0 = 1
    assert_eq!(is_simple_power(2, 2), true); // 2^1 = 2
    assert_eq!(is_simple_power(8, 2), true); // 2^3 = 8
    assert_eq!(is_simple_power(3, 2), false); // 2^1=2, 2^2=4; no integer power of 2 gives 3
    assert_eq!(is_simple_power(3, 1), false); // 1^k = 1 for any k; 3 != 1
    assert_eq!(is_simple_power(5, 3), false); // 3^1=3, 3^2=9; 5 not in between
    assert_eq!(is_simple_power(16, 2), true); // 2^4 = 16
    assert_eq!(is_simple_power(9, 3), true); // 3^2 = 9
    assert_eq!(is_simple_power(1, 1), false); // 1^k = 1, but we already handled x=1 as true, and n=1 should be false
    assert_eq!(is_simple_power(0, 2), false); // 2^k never gives 0
}
