/// Given a vector of non-negative integers, return a vector of the given vector after sorting,
/// you will sort the given vector in ascending order if the sum( first index value, last index value) is odd,
/// or sort it in descending order if the sum( first index value, last index value) is even.
/// Note:
/// * don't change the given vector.
/// Examples:
/// >>> sort_array(vec![])
/// Vec::<isize>::new()
/// >>> sort_array(vec![5])
/// vec![5]
/// >>> sort_array(vec![2, 4, 3, 0, 1, 5])
/// vec![0, 1, 2, 3, 4, 5]
/// >>> sort_array(vec![2, 4, 3, 0, 1, 5, 6])
/// vec![6, 5, 4, 3, 2, 1, 0]
fn sort_array(array: Vec<isize>) -> Vec<isize> {
    if array.is_empty() || array.len() == 1 {
        return array;
    }

    let first_last_sum = array[0] + array[array.len() - 1];

    if first_last_sum % 2 == 1 {
        // odd sum: sort in ascending order
        let mut sorted = array.clone();
        sorted.sort();
        sorted
    } else {
        // even sum: sort in descending order
        let mut sorted = array.clone();
        sorted.sort_by(|a, b| b.cmp(a));
        sorted
    }
}
```

