/// vec![-6, -5, -4, -3, -2]
/// >>> sort_array(vec![1, 0, 2, 3, 4])
/// vec![0, 1, 2, 3, 4]
fn sort_array(arr: Vec<isize>) -> Vec<isize> {
    arr.into_iter()
        .map(|x| (count_ones(x), x))
        .sorted_by(|a, b| {
            if a.0 == b.0 {
                a.1.cmp(&b.1)
            } else {
                a.0.cmp(&b.0)
            }
        })
        .map(|(_, x)| x)
        .collect()
}

fn count_ones(n: isize) -> usize {
    if n < 0 {
        // For negative numbers, we use two's complement representation
        // But since we're counting ones in binary, we can use the absolute value
        // and count the ones in the two's complement form, which is equivalent
        // to counting the ones in the absolute value of the number in two's complement
        // However, for sorting, we treat negative numbers by their magnitude
        // and use the same logic as positive: count the ones in the binary representation
        // of the absolute value, but note that negative numbers in two's complement
        // have a fixed bit length, so we can just count the ones in the absolute value
        // of the number, since the pattern of ones in the binary representation
        // of a negative number (in two's complement) is the same as the ones in the
        // absolute value of the number (in unsigned form).
        let abs_n = -n;
        let mut count = 0;
        let mut num = abs_n;
        while num != 0 {
            count += num & 1;
            num >>= 1;
        }
        count
    } else {
        let mut count = 0;
        let mut num = n;
        while num != 0 {
            count += num & 1;
            num >>= 1;
        }
        count
    }
}
