/// >>> prod_signs(vec![1, 2, 2, -4])
/// Some(9)
/// >>> prod_signs(vec![0, 1])
/// Some(0)
/// >>> prod_signs(vec![])
/// None
fn prod_signs(arr: Vec<isize>) -> Option<isize> {
    if arr.is_empty() {
        return None;
    }

    let sum_of_magnitudes: isize = arr.iter().map(|x| x.abs()).sum();
    let product_of_signs: isize = arr.iter().map(|x| {
        if *x == 0 {
            0
        } else if *x > 0 {
            1
        } else {
            -1
        }
    }).product();

    // If any element is 0, the product of signs becomes 0
    if product_of_signs == 0 {
        return Some(0);
    }

    Some(sum_of_magnitudes * product_of_signs)
}
