/// true
/// >>> is_nested(String::from("[[]][["))
/// true
fn is_nested(string: String) -> bool {
    let mut stack = Vec::new();
    let mut depths = Vec::new();

    for c in string.chars() {
        if c == '[' {
            stack.push(c);
            depths.push(stack.len());
        } else if c == ']' {
            if let Some(_) = stack.pop() {
                // When we close a bracket, we check if the depth is greater than 1
                // This means there was a bracket inside this one
                if depths.len() > 1 {
                    return true;
                }
            } else {
                // Invalid bracket sequence, but we still need to check for nesting
                // However, the problem says "valid subsequence", so we assume valid input
                // and only care about nested structure
            }
        }
    }

    // If we found a closing bracket that was nested inside another, we already returned true
    // Otherwise, no nesting occurred
    false
}
