fn compare(game: Vec<isize>, guess: Vec<isize>) -> Vec<isize> {
    let mut result = Vec::with_capacity(game.len());
    for (score, g) in game.iter().zip(guess.iter()) {
        result.push((score - g).abs());
    }
    result
}
