function pluck(arr: number[]): number[] {
  if (arr.length === 0) {
    return [];
  }

  let smallestEvenValue: number | null = null;
  let indexOfSmallestEven: number = -1;

  for (let i = 0; i < arr.length; i++) {
    if (arr[i] % 2 === 0) {
      if (smallestEvenValue === null || arr[i] < smallestEvenValue) {
        smallestEvenValue = arr[i];
        indexOfSmallestEven = i;
      }
    }
  }

  return smallestEvenValue === null ? [] : [smallestEvenValue, indexOfSmallestEven];
}
