function reverse_delete(s: string, c: string): [string, boolean] {
  // Create a Set of characters to delete from s
  const deleteSet = new Set(c);

  // Filter out characters in s that are in c
  const result = Array.from(s).filter(char => !deleteSet.has(char)).join('');

  // Check if result is a palindrome
  const isPalindrome = result === result.split('').reverse().join('');

  return [result, isPalindrome];
}
