function valid_date(date: string): boolean {
  // Check if the string is empty
  if (!date || date.trim() === '') {
    return false;
  }

  // Check if the format is mm-dd-yyyy (using hyphens only)
  const dateRegex = /^(\d{2})-(\d{2})-(\d{4})$/;
  if (!dateRegex.test(date)) {
    return false;
  }

  const [_, month, day, year] = date.match(dateRegex) as [string, string, string, string];

  // Validate month (1-12)
  const monthNum = parseInt(month, 10);
  if (monthNum < 1 || monthNum > 12) {
    return false;
  }

  // Validate day based on month
  const dayNum = parseInt(day, 10);
  if (dayNum < 1 || dayNum > 31) {
    return false;
  }

  // Days per month (non-leap year)
  const daysInMonth = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];

  // Check if day is valid for the given month
  if (dayNum > daysInMonth[monthNum - 1]) {
    return false;
  }

  // Special case: February in leap year
  // Leap year rule: divisible by 4, but not by 100 unless also by 400
  if (monthNum === 2 && dayNum === 29) {
    const yearNum = parseInt(year, 10);
    if ((yearNum % 4 !== 0) || (yearNum % 100 === 0 && yearNum % 400 !== 0)) {
      return false;
    }
  }

  return true;
}
