function prod_signs(arr: number[]): number | undefined {
  if (arr.length === 0) {
    return undefined;
  }

  let productOfSigns = 1;
  let sumOfMagnitudes = 0;

  for (const num of arr) {
    const magnitude = Math.abs(num);
    sumOfMagnitudes += magnitude;

    // Determine sign: 1 for positive, -1 for negative, 0 if number is 0
    if (num === 0) {
      productOfSigns = 0;
    } else if (num < 0) {
      productOfSigns *= -1;
    }
  }

  return sumOfMagnitudes * productOfSigns;
}
