```typescript
function is_nested(string: string): boolean {
  const stack: number[] = [];
  let has_nested = false;

  for (let i = 0; i < string.length; i++) {
    if (string[i] === '[') {
      stack.push(i);
    } else if (string[i] === ']') {
      if (stack.length > 0) {
        const openIndex = stack.pop();
        // If we have at least one opening bracket before this one, then we have a nested pair
        // But we need to check if there's a pair of brackets that are nested (i.e., one pair inside another)
        // So if we have a closing bracket after an opening bracket that was opened earlier, and that opening bracket was not the immediate parent,
        // then we have nesting.
        // Actually, we can detect nesting by checking if the current closing bracket corresponds to an opening bracket that was opened after a previous opening bracket.
        // So if we have a sequence like [ [ ] ] then we have nesting.
        // We can track the depth: if at any point the depth is greater than 1, then we have nesting.
        // Instead, we can just track the depth and see if it ever goes above 1.
      }
    }
  }

  // Simpler approach: track depth. If depth ever goes above 1, then we have nested brackets.
  let depth = 0;
  for (let i = 0; i < string.length; i++) {
    if (string[i] === '[') {
      depth++;
    } else if (string[i] === ']') {
      depth--;
    }
    if (depth > 1) {
      return true;
    }
  }

  return false;
}
```

