function simplify(x: string, n: string): boolean {
  // Parse x and n into numerator/denominator pairs
  const [xNum, xDen] = x.split('/').map(Number);
  const [nNum, nDen] = n.split('/').map(Number);

  // Compute the product: (xNum / xDen) * (nNum / nDen) = (xNum * nNum) / (xDen * nDen)
  const productNum = xNum * nNum;
  const productDen = xDen * nDen;

  // The product is a whole number if and only if productNum is divisible by productDen
  return productNum % productDen === 0;
}
```

